    while (true) {
        int c = 2*i+1; if (c >= n) break;
        if (c+1 < n && a[c+1] > a[c]) c++;         // bigger child
        if (a[i] >= a[c]) break;
        swap(a[i], a[c]); i = c;
    }
}
void heapsort(vector<int>& a){
    int n = a.size();
    for (int i = n/2 - 1; i >= 0; i--) sink(a, i, n);  // BUILD O(n)
    for (int e = n-1; e > 0; e--) {
        swap(a[0], a[e]);                              // champion to end
        sink(a, 0, e);                                 // shrink live region
    }
}

