def sink(a, i, n):
    while True:
        c = 2*i + 1
        if c >= n: break
        if c+1 < n and a[c+1] > a[c]: c += 1   # bigger child
        if a[i] >= a[c]: break
        a[i], a[c] = a[c], a[i]; i = c

def heapsort(a):
    n = len(a)
    for i in range(n//2 - 1, -1, -1):         # BUILD O(n)
        sink(a, i, n)
    for e in range(n-1, 0, -1):
        a[0], a[e] = a[e], a[0]               # champion to end
        sink(a, 0, e)                         # shrink live region
